  generationDelaySeconds: {what:'Waits this many seconds after startup before scanning the map and generating zones.', range:'Non-negative seconds. 0 starts immediately.', use:'Increase it when other systems need time to initialise or when startup performance is important.', related:'persistenceRecoveryDelaySeconds, persistenceEnabled', example:'12 is the documented default.'},
  maximumZones: {what:'Caps the total number of generated zones. Once the cap is reached, additional candidates are ignored.', range:'Positive whole number; larger values increase scan, persistence, and runtime cost.', use:'Raise it for large maps or dense settlements, but validate server performance and persistence size.', related:'minimumBuildingsPerCell, enableAdditionalUrbanCenters', example:'160 allows a broad civilian layout without unlimited generation.'},
  persistenceEnabled: {what:'Reuses previously calculated zones after a restart instead of scanning and placing everything from scratch.', range:'Boolean: true or false.', use:'Enable for stable public servers. Disable while testing detection changes or after changing the map.', related:'settlementCacheRevision, persistenceRecoveryDelaySeconds, persistenceRecoveryBatchSize', example:'Set settlementCacheRevision higher to force a fresh scan.'},
  settlementCacheRevision: {what:'Version number for the saved settlement cache. Changing it invalidates the old cache and forces recalculation.', range:'Any increasing integer.', use:'Increase after changing detection rules, map content, or zone-generation logic.', related:'persistenceEnabled, generationDelaySeconds', example:'Change 1 to 2 after a deliberate detection reset.'},
  zombieZoneEerieRainProbability: {what:'Chance that an eerie-weather activation chooses a rainy state when a player enters a zombie zone.', range:'Probability from 0 to 1 (0% to 100%).', use:'Use 0 for no rain from this rule; 1 makes every successful selection rainy.', related:'zombieZoneEerieWeatherEnabled, zombieZoneEerieLightningProbability, zombieZoneEerieWeatherState', example:'0.05 means roughly one rainy selection in twenty, not rain every twenty seconds.'},
