  persistenceRecoveryBatchDelayMilliseconds: {what:'Pause between batches while cached zones are restored.', range:'Milliseconds; 0 restores as fast as possible.', use:'Increase it to spread startup work over time and reduce a sharp server-load spike.', related:'persistenceRecoveryBatchSize, persistenceRecoveryDelaySeconds', example:'1000 ms with a batch size of 1 restores 160 zones over about 2 minutes 40 seconds.'}
  ,removeExistingAutomaticZones: {what:'Deletes previously generated automatic civilian zones before the new scan creates zones.', range:'Boolean: true or false.', use:'Enable when you want the scan to replace old automatic placements. Disable only when another system owns those zones.', related:'persistenceEnabled, settlementCacheRevision', example:'true prevents stale automatic zones from surviving a regeneration.'}
  ,disableAmbientCiviliansAutomaticZones: {what:'Sets the vanilla Ambient Civilians automatic location counts to zero while leaving STW civilian zones and vehicles active.', range:'Boolean: true or false.', use:'Enable when STW should provide the civilian activity and you want to avoid duplicate ambient civilian populations.', related:'showCivilianMarkers, removeExistingAutomaticZones', example:'true keeps STW zones active but suppresses the separate automatic ambient locations.'}
  ,persistenceRecoveryDelaySeconds: {what:'Additional wait after startup before cached civilian or zombie zones begin being restored.', range:'Seconds; 0 begins recovery immediately after the normal startup delay.', use:'Increase it when the server needs time to finish other startup work.', related:'generationDelaySeconds, persistenceRecoveryBatchSize, persistenceRecoveryBatchDelayMilliseconds', example:'120 delays cache recovery; 0 removes this extra wait.'}
  ,persistenceRecoveryBatchSize: {what:'Number of cached zones created in one recovery batch.', range:'Positive whole number.', use:'Larger batches restore faster but create a larger burst of work; smaller batches are gentler on server startup.', related:'persistenceRecoveryBatchDelayMilliseconds, persistenceRecoveryDelaySeconds', example:'1 is conservative; raising it restores several zones per batch.'}
  ,minimumBuildingsPerCell: {what:'Minimum number of recognized buildings required for a normal scan cell to qualify as a settlement candidate.', range:'Whole-number building count.', use:'Raise it to make automatic settlements rarer and more concentrated; lower it to include smaller built-up areas.', related:'mediumBuildingThreshold, largeBuildingThreshold, useHouseClustersAsSettlements', example:'3 accepts a cell containing at least three recognized buildings.'}
  ,detectIsolatedHousesAndFarms: {what:'Allows qualifying isolated homes and farms to become civilian-zone candidates even when they are not part of a dense settlement.', range:'Boolean: true or false.', use:'Enable for broader rural coverage; disable for towns-only civilian placement.', related:'minimumBuildingsPerCell, useHouseClustersAsSettlements', example:'true includes eligible isolated houses and farms.'}
  ,useChurchesAsSettlementAnchors: {what:'Uses churches as anchors for spread-out villages when enough buildings are found nearby.', range:'Boolean. The documented rule requires at least 3 buildings within 250 metres.', use:'Enable to recognize villages that are spatially spread out and would otherwise miss the normal cell test.', related:'churchSettlementAnchorRadius, churchSettlementMinimumBuildings, minimumBuildingsPerCell', example:'true can turn a church surrounded by three nearby buildings into a settlement.'}
  ,useHouseClustersAsSettlements: {what:'Treats a cluster of recognized houses as a settlement even when the houses cross scan-cell boundaries.', range:'Boolean. The documented rule is 3 recognized houses within 250 metres.', use:'Enable to avoid missing compact residential clusters because of grid boundaries.', related:'minimumBuildingsPerCell, detectIsolatedHousesAndFarms', example:'true recognizes three houses within the cluster radius as one settlement.'}
