  ,largeBuildingThreshold: {what:'Building-area threshold used when classifying a civilian settlement as large-sized.', range:'Numeric area/count threshold; normally higher than mediumBuildingThreshold.', use:'Raise it to reserve the large classification for denser areas; lower it to make large-zone behavior apply more often.', related:'mediumBuildingThreshold, maximumZones', example:'20 is the documented default threshold.'}
  ,enableAdditionalUrbanCenters: {what:'Allows the generator to place multiple useful centers inside a larger urban area instead of treating it as one center.', range:'Boolean: true or false.', use:'Enable for better coverage of large towns; disable for fewer, simpler zones.', related:'additionalSmallCenterSeparation, additionalMediumCenterSeparation, additionalLargeCenterSeparation', example:'true adds separated centers where the urban area is large enough.'}
  ,additionalSmallCenterSeparation: {what:'Minimum spacing between additional centers associated with small urban areas.', range:'Metres.', use:'Increase to spread small centers farther apart; decrease to permit denser coverage.', related:'enableAdditionalUrbanCenters, additionalMediumCenterSeparation, additionalLargeCenterSeparation', example:'100 m is the documented default.'}
  ,additionalMediumCenterSeparation: {what:'Minimum spacing between additional centers associated with medium urban areas.', range:'Metres.', use:'Increase to reduce the number of medium-area centers; decrease for more local coverage.', related:'enableAdditionalUrbanCenters, additionalSmallCenterSeparation, additionalLargeCenterSeparation', example:'160 m is the documented default.'}
  ,additionalLargeCenterSeparation: {what:'Minimum spacing between additional centers associated with large urban areas.', range:'Metres.', use:'Increase to make large-town centers more widely spaced; decrease to divide large areas into more centers.', related:'enableAdditionalUrbanCenters, additionalMediumCenterSeparation, maximumZones', example:'220 m is the documented default.'}
  ,excludeAirports: {what:'Prevents civilian settlement zones from being generated around airports.', range:'Boolean: true or false. The documented exclusion radius is 550 metres.', use:'Keep enabled to avoid placing civilian activity on runways or airport compounds.', related:'airportExclusionRadius, airportHardCoreRadius, allowDenseSettlementsNearAirports', example:'true excludes the airport perimeter from automatic civilian placement.'}
