  ,excludeHarbours: {what:'Prevents civilian settlement zones from being generated around recognized harbours.', range:'Boolean: true or false. When enabled, the documented radius is 300 metres.', use:'Enable when harbour facilities should not receive civilian settlement placement.', related:'excludeAirports, excludeMilitaryAreas', example:'false leaves harbour exclusion disabled by default.'}
