  ,fakeGunnerUseArmorPiercing: {what:'Allows simulated gunner fire to use armor-piercing projectile behavior.', range:'Boolean; current default false.', use:'Enable for stronger vehicle penetration; disable for ordinary ammunition behavior.', related:'fakeGunnerFire, fakeGunnerMaximumRangeMeters', example:'false uses non-armor-piercing simulated fire.'}
  ,fakeGunnerDispersionDegrees: {what:'Angular spread applied to simulated gunner fire.', range:'Degrees; current default 1.', use:'Increase for less accurate fire; decrease for tighter fire.', related:'fakeGunnerMaximumRangeMeters, fakeGunnerDistantShotIntervalSeconds', example:'1 degree is the current dispersion.'}
  ,fakeGunnerMaximumRangeMeters: {what:'Maximum range at which simulated gunner fire may be produced.', range:'Metres; current default 450.', use:'Increase for longer-range simulated fire; decrease to keep effects local.', related:'fakeGunnerDispersionDegrees, fakeGunnerDistanceThrottleRadiusMeters', example:'450 m is the maximum fake-gunner range.'}
  ,fakeGunnerDistantShotIntervalSeconds: {what:'Minimum interval between simulated gunner shots at distant targets.', range:'Seconds; current default 0.25.', use:'Increase to reduce distant fire rate and workload; decrease for more sustained distant fire.', related:'fakeGunnerDistanceThrottleRadiusMeters, projectileThreatDistantScanIntervalSeconds', example:'0.25 seconds spaces distant shots.'}
  ,fakeGunnerDistanceThrottleRadiusMeters: {what:'Distance beyond which simulated gunner fire is throttled.', range:'Metres; current default 1200.', use:'Increase to keep normal fire behavior farther away; decrease to throttle sooner.', related:'fakeGunnerDistantShotIntervalSeconds, fakeGunnerMaximumRangeMeters', example:'1200 m is the throttle radius.'}
  ,rocketDispersionDegrees: {what:'Angular spread applied to helicopter rocket runs.', range:'Degrees; current default 5.', use:'Increase for less precise rocket impacts; decrease for tighter runs.', related:'rocketRunsEnabled, automaticGroundEngagementRadiusMeters', example:'5 degrees is the current rocket dispersion.'}
  ,automaticGroundEngagementHoverSeconds: {what:'Time a helicopter hovers during automatic ground engagement.', range:'Seconds; current default 30.', use:'Raise for longer engagement windows; lower for quicker exposure reduction.', related:'automaticGroundEngagementEnabled, automaticGroundEngagementRadiusMeters, combatHoverMaximumRepositions', example:'30 seconds is the hover duration.'}
  ,combatHoverRepositionDamagePercent: {what:'Damage percentage that triggers a combat-hover reposition decision.', range:'Percentage; current default 3.', use:'Lower to reposition after smaller damage; raise to tolerate more damage before moving.', related:'combatHoverMaximumRepositions, returnToBaseHealthPercent', example:'3 triggers reposition behavior after a small damage amount.'}
  ,combatHoverMaximumRepositions: {what:'Maximum number of combat-hover reposition attempts during an engagement.', range:'Whole-number repositions; current default 2.', use:'Raise for more evasive movement; lower to limit repositioning.', related:'combatHoverRepositionDamagePercent, automaticGroundEngagementHoverSeconds', example:'2 repositions are allowed.'}
  ,dangerZoneScanIntervalMinutes: {what:'How often helicopter danger zones are scanned or refreshed.', range:'Minutes; current default 10.', use:'Lower for fresher danger information; raise to reduce scanning work.', related:'dangerZoneAvoidanceEnabled, dangerZoneExpiryMinutes', example:'10 minutes is the scan interval.'}
  ,dangerZoneExpiryMinutes: {what:'How long a normal helicopter danger zone remains active.', range:'Minutes; current default 30.', use:'Raise for longer avoidance; lower to resume route options sooner.', related:'dangerZoneRadiusMeters, recentCrashDangerZoneExpiryMinutes', example:'30 minutes is the normal danger-zone lifetime.'}
  ,recentCrashDangerZoneExpiryMinutes: {what:'How long a danger zone caused by a recent helicopter crash remains active.', range:'Minutes; current default 45.', use:'Raise to keep aircraft away from crash areas longer; lower to reopen routes sooner.', related:'recentCrashDangerZoneRadiusMeters, dangerZoneAvoidanceEnabled', example:'45 minutes protects a recent crash area.'}
  ,recentCrashDangerZoneRadiusMeters: {what:'Radius of a danger zone created around a recent helicopter crash.', range:'Metres; current default 1200.', use:'Increase for a wider crash avoidance area; decrease to limit route exclusion.', related:'recentCrashDangerZoneExpiryMinutes, dangerZoneRadiusMeters', example:'1200 m is the crash danger radius.'}
  ,repairTargetHealthPercent: {what:'Health percentage helicopters are repaired to before takeoff or after maintenance.', range:'Percentage; current default 100.', use:'Lower to allow damaged aircraft to return sooner; keep at 100 for fully repaired aircraft.', related:'repairBeforeTakeoff, repairDelayBaseSeconds, returnToBaseHealthPercent', example:'100 repairs to full health.'}
