  ,repairDelaySecondsPerDamagePercent: {what:'Additional repair time applied per percentage point of damage.', range:'Seconds per damage percent; current default 3.', use:'Raise to make heavily damaged aircraft take longer; lower for faster repair.', related:'repairDelayBaseSeconds, repairDelayMaximumSeconds', example:'3 seconds are added per damage percent.'}
  ,repairDelayMaximumSeconds: {what:'Maximum total repair delay for a helicopter.', range:'Seconds; current default 300.', use:'Raise for a stronger repair-time cap; lower to bound turnaround delay.', related:'repairDelayBaseSeconds, repairDelaySecondsPerDamagePercent', example:'300 seconds caps repair at five minutes.'}
  ,targetUSArmoredCount: {what:'Desired number of active US-aligned armored support vehicles.', range:'Whole-number vehicle count; current default 2.', use:'Raise for more US armored support; lower to reduce armored presence.', related:'targetUSSRArmoredCount, minimumArmoredSeparation, maximumPlacementAttempts', example:'2 requests two US-aligned armored vehicles.'}
  ,targetUSSRArmoredCount: {what:'Desired number of active USSR-aligned armored support vehicles.', range:'Whole-number vehicle count; current default 4.', use:'Raise for more USSR armored support; lower to reduce armored presence.', related:'targetUSArmoredCount, minimumArmoredSeparation, maximumPlacementAttempts', example:'4 requests four USSR-aligned armored vehicles.'}
  ,minimumArmoredSeparation: {what:'Minimum distance kept between generated armored support vehicles.', range:'Metres; current default 500.', use:'Increase to spread vehicles across the map; decrease if valid placement areas are scarce.', related:'targetUSArmoredCount, targetUSSRArmoredCount, maximumPlacementAttempts', example:'500 m prevents armored vehicles from clustering too closely.'}
  ,maximumTerrainSlopeDegrees: {what:'Maximum terrain slope accepted for armored vehicle placement.', range:'Degrees; current default 8.', use:'Lower for flatter, safer vehicle positions; raise to allow rougher terrain.', related:'terrainSampleDistance, obstacleClearanceRadius, maximumPlacementAttempts', example:'8 degrees is the current placement limit.'}
