  ,maximumPlacementAttempts: {what:'Maximum candidate positions tested before armored placement gives up for that request.', range:'Whole-number attempts; current default 40.', use:'Raise to find a valid position on difficult maps at the cost of more generation work.', related:'minimumArmoredSeparation, maximumTerrainSlopeDegrees', example:'40 attempts are allowed for one placement request.'}
  ,onRoadProbability: {what:'Chance that an armored vehicle placement prefers a position on a road.', range:'0 to 1; current default about 0.70.', use:'Raise for more road-based placements; lower for more off-road positions.', related:'onRoadAlignedProbability, nearRoadDistance', example:'0.70 means roughly seventy percent of eligible choices prefer roads.'}
