  ,nearRoadDistance: {what:'Distance from a road within which a near-road armored placement is considered.', range:'Metres; current default 30.', use:'Increase to make more positions qualify as near-road; decrease to keep them close to the road.', related:'nearRoadAlignedProbability, nearRoadPerpendicularProbability', example:'30 m defines the near-road band.'}
