  ,nearRoadPerpendicularProbability: {what:'Chance that a near-road armored vehicle is placed perpendicular to the road.', range:'0 to 1; current default about 0.30.', use:'Raise for more cross-road defensive positions; lower for fewer perpendicular placements.', related:'nearRoadAlignedProbability, nearRoadDistance', example:'0.30 gives a thirty-percent perpendicular preference.'}
  ,enableCombatSupportRailTransit: {what:'Allows armored support vehicles to use the support-rail transit system when responding to requests.', range:'Boolean; current default true.', use:'Disable to prevent rail-style support movement; enable for controlled support transit.', related:'combatSupportRailSpeedMetersPerSecond, combatSupportRailPlayerExclusionMeters, enableCombatSupportRailSnapRecovery', example:'true enables rail transit.'}
  ,combatSupportRailSpeedMetersPerSecond: {what:'Transit speed used by armored vehicles moving along the support rail.', range:'Metres per second; current default 18.', use:'Raise for faster support arrival; lower for more conservative movement.', related:'combatSupportRailUpdateMilliseconds, supportEtaExpiryMultiplier', example:'18 m/s is the current rail speed.'}
  ,combatSupportRailPlayerExclusionMeters: {what:'Distance around players where support-rail movement avoids or changes behavior.', range:'Metres; current default 450.', use:'Increase for a wider player safety buffer; decrease if routes are too restricted.', related:'enableCombatSupportRailTransit, combatSupportRailDistantUpdateMilliseconds', example:'450 m is the current exclusion buffer.'}
  ,combatSupportRailSnapMaximumMeters: {what:'Maximum correction distance allowed when rail transit snap recovery repairs a vehicle position.', range:'Metres; current default 200.', use:'Raise to recover larger navigation errors; lower to prevent surprising long corrections.', related:'enableCombatSupportRailSnapRecovery, combatSupportRailSnapCandidateCount', example:'200 m is the maximum snap correction.'}
  ,supportEtaExpiryMultiplier: {what:'Multiplier applied to estimated support arrival time before the request is considered expired.', range:'Numeric multiplier; current default 2.', use:'Raise to tolerate slower arrivals; lower to expire late support requests sooner.', related:'supportEtaExpiryMinimumSeconds, combatSupportRailSpeedMetersPerSecond', example:'2 allows an expiry window about twice the estimate.'}
  ,supportEtaExpiryMinimumSeconds: {what:'Minimum amount of time a support request remains valid regardless of its estimated arrival.', range:'Seconds; current default 120.', use:'Raise to keep requests alive longer; lower to discard stale requests sooner.', related:'supportEtaExpiryMultiplier, combatSupportRailSpeedMetersPerSecond', example:'120 guarantees at least two minutes.'}
  ,crewAbsenceRecoverySeconds: {what:'Time before the armored system attempts to recover or rebuild missing vehicle crew.', range:'Seconds; current default 300.', use:'Lower for faster crew recovery; raise to avoid repeated recovery attempts during transient states.', related:'vehicleMaintenanceIntervalSeconds, targetUSArmoredCount', example:'300 waits five minutes.'}
  ,vehicleMaintenanceIntervalSeconds: {what:'How often armored vehicle maintenance checks run.', range:'Seconds; current default 600.', use:'Lower for more frequent maintenance; raise to reduce periodic checks.', related:'crewAbsenceRecoverySeconds, enableVehicleTTL', example:'600 runs maintenance about every ten minutes.'}
  ,enableVehicleTTL: {what:'Enables a maximum lifetime for armored vehicles managed by the lifecycle system.', range:'Boolean; current default true.', use:'Disable if vehicles should not expire by age; enable to prevent indefinite accumulation.', related:'maxLifetimeSeconds, vehicleMaintenanceIntervalSeconds', example:'true applies the vehicle lifetime limit.'}
