  ,playerSafeRadiusMeters: {what:'Minimum distance from players required for an armored vehicle respawn candidate.', range:'Metres; current default 1500.', use:'Increase for safer respawns; decrease if maps have too few valid candidates.', related:'candidateAttempts, minimumRespawnMinutes', example:'1500 m prevents respawns close to players.'}
