  ,targetUSTankCount: {what:'Desired number of US-aligned tanks maintained by the tank support system.', range:'Whole-number tank count; current default 1.', use:'Raise for more US tanks; lower to reduce armored presence.', related:'targetAFRFTankCount, minimumTankSeparation, maximumPlacementAttemptsPerArea', example:'1 requests one US-aligned tank.'}
  ,targetAFRFTankCount: {what:'Desired number of AFRF-aligned tanks maintained by the tank support system.', range:'Whole-number tank count; current default 3.', use:'Raise for more AFRF tanks; lower to reduce armored presence.', related:'targetUSTankCount, minimumTankSeparation, allowedTankEraTags', example:'3 requests three AFRF-aligned tanks.'}
  ,minimumTankSeparation: {what:'Minimum distance between generated tanks.', range:'Metres; current default 500.', use:'Increase to spread tanks out; decrease when valid placement space is limited.', related:'targetUSTankCount, targetAFRFTankCount, spawnAreaRadius', example:'500 m prevents tanks from clustering.'}
  ,spawnAreaRadius: {what:'Radius around a selected tank support area in which a valid tank position may be found.', range:'Metres; current default 130.', use:'Increase to give placement more room; decrease to keep tanks closer to the selected area.', related:'minimumTankSeparation, maximumPlacementAttemptsPerArea, maximumTerrainSlopeDegrees', example:'130 m is the current placement area radius.'}
  ,maximumPlacementAttemptsPerArea: {what:'Maximum candidate positions tested in one tank spawn area.', range:'Whole-number attempts; current default 24.', use:'Raise for difficult terrain or crowded maps; lower to reduce placement work.', related:'spawnAreaRadius, maximumTerrainSlopeDegrees, obstacleClearanceRadius', example:'24 attempts are made before the area is rejected.'}
  ,localDefenseEnabled: {what:'Enables local defensive behavior for tanks around their assigned area.', range:'Boolean; current default true.', use:'Disable to keep tanks from reacting locally; enable for more active area defense.', related:'localDefenseDetectionRadius, localDefenseEngagementRadius, localDefenseResponseMoveRadius', example:'true enables local tank defense.'}
  ,localDefenseDetectionRadius: {what:'Distance within which a tank detects threats for local defense behavior.', range:'Metres; current default 350.', use:'Increase to detect threats farther away; decrease for a tighter defensive perimeter.', related:'localDefenseEngagementRadius, localDefenseMaximumRoamDistance', example:'350 m is the detection radius.'}
  ,localDefenseEngagementRadius: {what:'Distance within which local tank defense may engage a detected threat.', range:'Metres; current default 500.', use:'Increase for longer-range local engagement; decrease to keep tanks closer to their post.', related:'localDefenseDetectionRadius, localDefenseResponseMoveRadius', example:'500 m is the current engagement radius.'}
  ,localDefenseResponseMoveRadius: {what:'Maximum response movement radius used when a tank reacts to a local defense threat.', range:'Metres; current default 250.', use:'Increase for more mobile defense; decrease to keep tanks near their starting area.', related:'localDefenseEngagementRadius, localDefenseMaximumRoamDistance', example:'250 m limits the response move.'}
