  ,enableTankSupportHintMessages: {what:'Shows tank support status as on-screen hints.', range:'Boolean; current default false.', use:'Enable for visible player feedback; disable if hints are intrusive.', related:'enableTankSupportChatMessages, enableTankSupportSoundMessages', example:'false suppresses tank-support hints.'}
