  ,automaticSortieTurnaroundMaximumMinutes: {what:'Longest turnaround delay before an automatic helicopter can begin another sortie.', range:'Minutes; current default 15.', use:'Raise for more downtime; lower for more frequent support.', related:'automaticSortieTurnaroundMinimumMinutes, maxConcurrentSorties', example:'15 minutes is the maximum turnaround.'}
  ,automaticGroundEngagementEnabled: {what:'Allows combat helicopters to engage eligible ground targets automatically during sorties.', range:'Boolean; current default true.', use:'Disable for transport or flyby-only behavior; enable for automatic attack support.', related:'automaticGroundEngagementRadiusMeters, maximumGroundEngagementsPerSortie, rocketRunsEnabled', example:'true enables automatic ground engagement.'}
