  ,rocketRunsEnabled: {what:'Allows automatic helicopter rocket attack runs.', range:'Boolean; current default true.', use:'Disable to suppress rocket attacks while retaining other helicopter behavior.', related:'rocketDispersionDegrees, automaticGroundEngagementEnabled', example:'true enables rocket runs.'}
