  ,replaceMissingCrewBeforeTakeoff: {what:'Requires missing helicopter crew to be replaced before an aircraft takes off.', range:'Boolean; current default true.', use:'Keep enabled for complete crews; disable only when partial crews are intentional.', related:'parkedCrewRecoveryDelaySeconds, parkedCrewRecoveryPlayerSafetyRadiusMeters', example:'true replaces missing crew before takeoff.'}
  ,refuelBeforeTakeoff: {what:'Refuels a helicopter before an automatic sortie when needed.', range:'Boolean; current default true.', use:'Keep enabled for reliable sortie preparation; disable for stricter fuel logistics.', related:'rearmBeforeTakeoff, repairBeforeTakeoff, refuelThreshold', example:'true ensures fuel preparation before launch.'}
  ,rearmBeforeTakeoff: {what:'Rearms a helicopter before an automatic sortie when needed.', range:'Boolean; current default true.', use:'Keep enabled for fully equipped sorties; disable when ammunition scarcity is desired.', related:'refuelBeforeTakeoff, repairBeforeTakeoff, sortieDurationMinutes', example:'true rearms before launch.'}
  ,repairBeforeTakeoff: {what:'Repairs a helicopter before an automatic sortie when needed.', range:'Boolean; current default true.', use:'Keep enabled for reliable aircraft; disable to let damage carry into future sorties.', related:'repairTargetHealthPercent, repairDelayBaseSeconds, returnToBaseHealthPercent', example:'true repairs before takeoff.'}
