  ,emptyVehicleReplacementTimeoutSeconds: {what:'How long an empty light vehicle may remain before replacement handling is considered.', range:'Seconds; current default 1800.', use:'Lower to recycle abandoned vehicles sooner; raise to preserve vehicles during temporary crew absence.', related:'crewAbsenceRecoverySeconds, vehicleMaintenanceIntervalSeconds', example:'1800 seconds is thirty minutes.'}
