  ,maximumTotalHives: {what:'Global maximum number of zombie hives created by the zombie system.', range:'Whole-number hives; current default 48.', use:'Raise for more total zombie population; lower to reduce AI and spawn workload.', related:'populationPerHive, maximumHivesPerZone, zombiesPerHive', example:'48 hives is the global cap.'}
