  ,zombieZoneEerieLightningCooldownSeconds: {what:'Minimum time between eerie-weather lightning attempts.', range:'Seconds; current default 45.', use:'Raise for less frequent lightning; lower for more frequent attempts.', related:'zombieZoneEerieLightningProbability, zombieZoneEerieWeatherEnabled', example:'45 seconds separates lightning attempts.'}
  ,patrolProbability: {what:'Chance that an eligible armored vehicle participates in a patrol.', range:'0 to 1; current default about 0.90.', use:'Raise for more patrol activity; lower for more stationary or support-only vehicles.', related:'maximumActivePatrols, wheeledPatrolWeight', example:'0.90 gives most eligible vehicles a patrol role.'}
  ,maximumActivePatrols: {what:'Maximum number of active armored patrols.', range:'Whole-number patrols; current default 64.', use:'Raise for more patrol traffic; lower to reduce route and vehicle workload.', related:'patrolProbability, startStaggerSeconds', example:'64 is the patrol cap.'}
  ,minimumStopSeconds: {what:'Shortest stop duration during an armored patrol.', range:'Seconds; current default 30.', use:'Raise for longer patrol pauses; lower for more continuous movement.', related:'maximumStopSeconds, stopProbability', example:'30 seconds is the minimum stop.'}
  ,maximumStopSeconds: {what:'Longest stop duration during an armored patrol.', range:'Seconds; current default 120.', use:'Raise for longer pauses; lower for faster patrol circulation.', related:'minimumStopSeconds, stopProbability', example:'120 seconds is the maximum stop.'}
