  ,poiMinimumDistance: {what:'Minimum distance from a point of interest used when selecting patrol destinations.', range:'Metres; current default 600.', use:'Raise to keep patrols farther from the origin; lower for more local patrols.', related:'poiMaximumDistance, roadLegMinimumDistance', example:'600 m is the minimum POI distance.'}
  ,poiMaximumDistance: {what:'Maximum distance from a point of interest used when selecting patrol destinations.', range:'Metres; current default 5000.', use:'Raise for broader patrol routes; lower for tighter local patrols.', related:'poiMinimumDistance, maximumActivePatrols', example:'5000 m is the maximum POI distance.'}
  ,roadLegMinimumDistance: {what:'Minimum length of a selected road leg in an armored patrol route.', range:'Metres; current default 300.', use:'Raise for longer route segments; lower for shorter, more frequent turns.', related:'roadLegMaximumDistance, roadNodeSpacing', example:'300 m is the minimum road leg.'}
  ,roadLegMaximumDistance: {what:'Maximum length of a selected road leg in an armored patrol route.', range:'Metres; current default 900.', use:'Raise for longer patrol legs; lower for more local route movement.', related:'roadLegMinimumDistance, failedLegRetrySeconds', example:'900 m is the maximum road leg.'}
  ,enableStuckTeleportRecovery: {what:'Allows armored patrols to teleport to a safe candidate when route recovery cannot free them.', range:'Boolean; current default true.', use:'Enable for resilient patrols; disable when vehicles must never teleport.', related:'stuckTimeoutSeconds, stuckTeleportMinimumMeters, maximumStuckTeleportsPerPatrol', example:'true enables patrol teleport recovery.'}
