  ,enableRandomVehicleResupplyCrate: {what:'Allows random vehicle-resupply crates to be generated.', range:'Boolean; current default true.', use:'Disable to remove vehicle resupply crates.', related:'enableRandomCrate, weaponsCatalogPath', example:'true enables vehicle resupply.'}
