  ,automaticGenerationEnabled: {what:'Enables automatic Special Forces team generation.', range:'Boolean; current default true.', use:'Disable for manually placed teams only; enable for automatic teams.', related:'automaticGenerationFactions, maximumActiveTeams, minimumTeamSeparationMeters', example:'true enables automatic generation.'}
