  ,enableDynamicWorldScanner: {what:'Enables Task Commander’s background scan for usable buildings and world locations.', range:'Boolean; current default true.', use:'Keep enabled for dynamic task discovery; disable to rely only on fixed or previously known locations.', related:'dynamicWorldScanIntervalMinutes, dynamicWorldScanTileSizeMeters, enableIntelTasks', example:'true enables background scanning.'}
