  ,dynamicWorldScanMaxTilesPerBatch: {what:'Maximum number of world-scan tiles processed in one batch.', range:'Whole-number tiles; current default 1.', use:'Raise for faster scanning; lower to spread scan work over time.', related:'dynamicWorldScanMaxBatchMilliseconds, dynamicWorldScanBatchYieldMilliseconds', example:'1 tile is processed per batch.'}
