  ,dynamicWorldScanIntervalMinutes: {what:'Interval between full or continuing dynamic world-scan passes.', range:'Minutes; current default 60.', use:'Lower for fresher task locations; raise to reduce scanning activity.', related:'enableDynamicWorldScanner, dynamicWorldScanTileSizeMeters', example:'60 minutes is the scan interval.'}
