  ,enableIntelTasks: {what:'Allows intelligence-gathering tasks to be selected.', range:'Boolean; current default true.', use:'Disable to remove intel tasks from the task pool while keeping other task types.', related:'intelTaskChancePercent, maximumDocumentsPerCache, enableDynamicWorldScanner', example:'true enables intel tasks.'}
