  ,enableLeaderTasks: {what:'Allows tasks involving enemy leaders or leader targets.', range:'Boolean; current default true.', use:'Disable to remove leader-target tasks from selection.', related:'leaderTaskChancePercent, loneWolfLeaderTaskChancePercent', example:'true enables leader tasks.'}
