  ,carTaskChancePercent: {what:'Relative chance that a generated task is a car task.', range:'Percentage; current default 10.', use:'Raise to favor car tasks; lower to make them less common.', related:'enableCarTasks, apcTaskChancePercent, tankTaskChancePercent', example:'10 gives car tasks a ten-percent weight.'}
  ,enableAPCTasks: {what:'Allows APC tasks to be selected.', range:'Boolean; current default true.', use:'Disable to remove APC objectives from task generation.', related:'apcTaskChancePercent, enableTankTasks', example:'true enables APC tasks.'}
