  ,tankTaskChancePercent: {what:'Relative chance that a generated task is a tank task.', range:'Percentage; current default 10.', use:'Raise to favor tank objectives; lower to reduce them.', related:'enableTankTasks, apcTaskChancePercent, helicopterTaskChancePercent', example:'10 gives tank tasks a ten-percent weight.'}
  ,enableHelicopterTasks: {what:'Allows helicopter tasks to be selected.', range:'Boolean; current default true.', use:'Disable to remove helicopter objectives from task generation.', related:'helicopterTaskChancePercent, enableOtherVehicleTasks', example:'true enables helicopter tasks.'}
  ,helicopterTaskChancePercent: {what:'Relative chance that a generated task is a helicopter task.', range:'Percentage; current default 5.', use:'Raise to favor air objectives; lower to make them rarer.', related:'enableHelicopterTasks, tankTaskChancePercent', example:'5 gives helicopter tasks a five-percent weight.'}
