  ,GenerateArsenals: {what:'Allows the Bases system to place arsenal objects at generated bases.', range:'Boolean; current value true.', use:'Disable for spawn bases without arsenals; enable for bases intended to provide equipment access.', related:'Arsenals, GenerateMarkers, STWBasesCratesIntegrationConfig', example:'true generates configured arsenals.'}
