  ,Count: {what:'Number of spawn points or initial groups generated for the surrounding configuration object.', range:'Whole-number count; meaning depends on the containing section.', use:'Raise for more spawn points or groups; lower for lighter faction presence.', related:'SpawnPoint, InitialGroups, factionKey', example:'A SpawnPoint Count of 12 creates twelve configured spawn points.'}
