  ,MinimumSeparation: {what:'Minimum distance between same-faction base or crate placements.', range:'Metres; base values are commonly 200 or 1500, integration default 3.', use:'Increase to spread placements; decrease only when locations are scarce.', related:'MinimumHostileSeparation, MaximumPlacementAttempts', example:'1500 m separates the current US/AFRF base spawn points.'}
