  ,RandomizeOrientation: {what:'Randomizes orientation of an integrated crate instead of preserving a fixed or arsenal-aligned orientation.', range:'Boolean; current default false.', use:'Enable for visual variation; disable for predictable placement.', related:'UseArsenalOrientation, PreferArsenal', example:'false keeps orientation predictable.'}
  ,targetBoatCount: {what:'Desired number of active boats maintained by the Boat system.', range:'Whole-number boat count; current default 3.', use:'Raise for more waterborne activity; lower to reduce boat presence.', related:'minimumBoatSeparation, minimumWaterDepth, maximumPlacementAttemptsPerPOI', example:'3 requests three boats.'}
