  ,maximumMarkerOffsetDistance: {what:'Maximum offset applied when boat marker positions are not precise.', range:'Metres; current default 75.', use:'Lower for more accurate approximate markers; raise for more privacy or visual separation.', related:'preciseMarkerPositions, showBoatMarkers', example:'75 m is the maximum marker offset.'}
  ,camouflage: {what:'Camouflage selection used for generated sniper pairs.', range:'Named camouflage or RANDOM; current default RANDOM.', use:'Choose a specific environment pattern for consistency or RANDOM for map variation.', related:'camouflageAllowlist, sniperRifle, sniperOptic', example:'RANDOM selects from the allowed camouflage list.'}
