  ,sniperRifle: {what:'Weapon selection used for the sniper in a generated pair.', range:'Named weapon or RANDOM; current default RANDOM.', use:'Select a specific rifle for consistent loadouts or leave RANDOM for variety.', related:'sniperOptic, sniperMuzzle, magazineMinimum, magazineMaximum', example:'RANDOM chooses an eligible rifle.'}
  ,spotterWeapon: {what:'Weapon selection used for the spotter in a generated sniper pair.', range:'Named weapon or RANDOM; current default RANDOM.', use:'Select a specific spotter weapon or leave RANDOM for variety.', related:'spotterOptic, spotterMuzzle, sniperRifle', example:'RANDOM chooses an eligible spotter weapon.'}
