  ,sniperOptic: {what:'Optic selection used by the sniper.', range:'Named optic or RANDOM; current default RANDOM.', use:'Choose a specific optic for a known engagement distance or leave RANDOM for variation.', related:'sniperRifle, sniperMuzzle', example:'RANDOM selects an eligible sniper optic.'}
  ,spotterOptic: {what:'Optic selection used by the spotter.', range:'Named optic or RANDOM; current default RANDOM.', use:'Choose a specific observation optic or leave RANDOM for variation.', related:'spotterWeapon, spotterMuzzle', example:'RANDOM selects an eligible spotter optic.'}
  ,nightVision: {what:'Night-vision selection for the generated sniper pair.', range:'Named setting or RANDOM; current value RANDOM.', use:'Use RANDOM for varied equipment or a specific setting to control night capability.', related:'camouflage, sniperOptic, spotterOptic', example:'RANDOM allows the loadout system to choose.'}
  ,enableBalaclavas: {what:'Allows balaclavas to be included in generated sniper loadouts.', range:'Boolean; current default true.', use:'Disable for a more recognizable appearance; enable for concealed sniper visuals.', related:'camouflage, sniperRifle', example:'true allows balaclavas.'}
