  ,Enabled: {what:'Master switch for Mobile Spawn.', range:'Boolean; current default true.', use:'Disable to stop the mobile-spawn feature while preserving its saved configuration.', related:'PersistenceEnabled, EnableRuntimeSpawnPoint', example:'true enables Mobile Spawn.'}
  ,PersistenceEnabled: {what:'Saves and restores Mobile Spawn associations and state across server restarts.', range:'Boolean; current default true.', use:'Enable for persistent mobile spawn behavior; disable for a clean transient session.', related:'Enabled, EnableRuntimeSpawnPoint', example:'true restores saved state.'}
