  ,Enabled: {what:'Master switch for the mobile spawn system.', range:'Boolean: true or false.', use:'Disable it to stop mobile spawn processing without removing the configured prefabs.', related:'PersistenceEnabled, EnableRuntimeSpawnPoint, DefaultFactionKey', example:'true allows eligible mobile spawn points to be created and watched.'}
