  ,MovementSpeedThreshold: {what:'Speed below which a watched object is considered stopped.', range:'Engine speed units per second; very small values detect a stop quickly.', use:'Increase it if a vehicle never settles because of tiny physics movement; decrease it if moving objects are mistaken for stopped.', related:'StopDebounceSeconds, WatchIntervalMilliseconds', example:'0.05 treats near-stationary movement as stopped.'}
  ,StopDebounceSeconds: {what:'Time the object must remain below the movement threshold before the spawn point is updated.', range:'Seconds.', use:'Increase it to avoid updates during brief pauses; decrease it for quicker deployment.', related:'MovementSpeedThreshold, WatchIntervalMilliseconds', example:'2 seconds filters out momentary speed dips.'}
  ,destroyedCrateContentsMode: {what:'Chooses what happens to items when a persistent crate is destroyed.', range:'Documented choices include scatter; use only supported mode names.', use:'Scatter leaves recoverable items around the destroyed crate instead of silently deleting everything.', related:'destroyedCrateMaximumRecoverableItems, destroyedCrateScatterRadius, removeEmptyCratesOnRecovery', example:'scatter creates a small item field around the former crate.'}
