  ,camouflage: {what:'Selects the clothing camouflage used by generated sniper teams.', range:'Supported name or RANDOM; RANDOM chooses from the allowlist.', use:'Use a fixed environment-appropriate scheme for predictable visuals, or RANDOM for variety.', related:'camouflageAllowlist, nightVision, sniperRifle', example:'Forest restricts the team to forest camouflage when supported.'}
  ,sniperRifle: {what:'Weapon selection rule for the sniper.', range:'Supported weapon identifier or RANDOM.', use:'Choose a specific rifle for faction or scenario consistency; RANDOM lets the catalog decide.', related:'sniperOptic, sniperMuzzle, magazineMinimum, magazineMaximum', example:'RANDOM avoids hard-coding one rifle across every generated team.'}
  ,magazineMinimum: {what:'Minimum number of magazines assigned to the generated sniper or spotter loadout.', range:'Whole number; should not exceed magazineMaximum.', use:'Raise it for longer independent operations; lower it to make ammunition scarce.', related:'magazineMaximum, fragmentationGrenades, smokeGrenades', example:'5 gives a modest reserve without overloading the unit.'}
  ,magazineMaximum: {what:'Maximum number of magazines assigned to the generated loadout.', range:'Whole number; should be at least magazineMinimum.', use:'Raise it when teams routinely run dry before resupply; lower it to limit inventory weight and loot.', related:'magazineMinimum, sniperRifle, spotterWeapon', example:'7 permits a loadout to receive between five and seven magazines.'}
  ,spotterWeapon: {what:'Weapon selection rule for the sniper’s spotter.', range:'Supported weapon identifier or RANDOM.', use:'The spotter normally receives a complementary weapon; choose a fixed value for a themed unit or RANDOM for variety.', related:'sniperRifle, spotterOptic, spotterMuzzle', example:'RANDOM lets the configured catalog choose a suitable spotter weapon.'}
  ,sniperMuzzle: {what:'Muzzle attachment rule for the sniper rifle.', range:'Supported attachment identifier or RANDOM.', use:'A suppressor reduces the team’s signature; another supported muzzle can be selected when the scenario needs a different compromise.', related:'sniperRifle, sniperOptic, spotterMuzzle', example:'Suppressor gives the sniper a quieter firing profile.'}
  ,spotterMuzzle: {what:'Muzzle attachment rule for the spotter weapon.', range:'Supported attachment identifier or RANDOM.', use:'Keep it aligned with the intended stealth level of the team.', related:'spotterWeapon, sniperMuzzle, camouflage', example:'Suppressor keeps the spotter from immediately revealing the position.'}
  ,sniperOptic: {what:'Optic selection rule for the sniper rifle.', range:'Supported optic identifier or RANDOM.', use:'Use a fixed long-range optic for predictable engagements, or RANDOM for equipment variety.', related:'sniperRifle, sniperMuzzle, nightVision', example:'RANDOM allows different valid optics without changing the config.'}
  ,spotterOptic: {what:'Optic selection rule for the spotter weapon.', range:'Supported optic identifier or RANDOM.', use:'Choose an optic that supports observation without making every spotter identical.', related:'spotterWeapon, sniperOptic, nightVision', example:'RANDOM gives the spotter a valid catalog optic.'}
  ,nightVision: {what:'Night-vision equipment selection rule for the generated team.', range:'Supported identifier or RANDOM; exact availability depends on the faction catalog.', use:'Use a fixed value for a night-operation scenario or RANDOM to follow the available loadout pool.', related:'camouflage, sniperOptic, enableBalaclavas', example:'RANDOM lets the faction’s valid night-vision options decide.'}
  ,enableBalaclavas: {what:'Allows generated snipers and spotters to receive balaclavas where the loadout supports them.', range:'Boolean: true or false.', use:'Disable it when facial visibility or a lighter appearance is preferred.', related:'camouflage, nightVision, enableChatMessages', example:'true permits balaclavas but does not guarantee every unit receives one.'}
  ,showBoatMarkers: {what:'Shows generated boat positions to players through map markers.', range:'Boolean: true or false.', use:'Enable for administrators or public transport gameplay; disable to keep boat locations undisclosed.', related:'markerZoomThreshold, preciseMarkerPositions, maximumMarkerOffsetDistance', example:'false keeps the boats discoverable only in the world.'}
  ,preciseMarkerPositions: {what:'Controls whether boat markers use the exact placement position instead of an intentionally approximate position.', range:'Boolean: true or false.', use:'Enable for administration and testing; disable when markers should not reveal an exact asset location.', related:'showBoatMarkers, maximumMarkerOffsetDistance', example:'true makes the marker correspond closely to the boat.'}
  ,maximumMarkerOffsetDistance: {what:'Maximum distance by which a deliberately imprecise boat marker may be offset.', range:'Metres.', use:'Increase it for less precise public information; set it low for more useful administration markers.', related:'preciseMarkerPositions, showBoatMarkers', example:'75 m keeps an imprecise marker in the general shoreline area.'}
  ,PersistenceEnabled: {what:'Stores the mobile spawn system’s state so it can be restored after a restart.', range:'Boolean: true or false.', use:'Enable for persistent campaigns; disable while testing spawn-point changes or clearing old state.', related:'Enabled, EnableRuntimeSpawnPoint, DefaultFactionKey', example:'true helps a deployed mobile spawn remain available after a restart.'}
