  ,intelligenceRevealErrorRadiusMeters: {what:'Uncertainty radius applied to an intelligence reveal marker or report.', range:'Metres.', use:'Increase it to make reports less precise; decrease it for more actionable intelligence.', related:'intelligenceRevealProbability, intelligenceRevealHintDurationSeconds, intelligenceRevealIntervalMinSeconds', example:'250 m communicates an approximate area rather than an exact position.'}
  ,intelligenceRevealProbability: {what:'Chance that an eligible intelligence reveal is generated.', range:'Probability from 0 to 1 or percentage according to the file’s convention.', use:'Raise it for more frequent strategic information; lower it to preserve fog of war.', related:'intelligenceRevealIntervalMinSeconds, intelligenceRevealIntervalMaxSeconds, intelligenceRevealErrorRadiusMeters', example:'0.25 produces reveals on roughly one quarter of eligible evaluations.'}
  ,intelligenceRevealIntervalMinSeconds: {what:'Shortest interval between automatic intelligence reveals.', range:'Seconds; should not exceed the maximum.', use:'Lower it for more frequent information; raise it to slow the intelligence flow.', related:'intelligenceRevealIntervalMaxSeconds, intelligenceRevealProbability', example:'The next reveal cannot occur before this interval.'}
  ,intelligenceRevealIntervalMaxSeconds: {what:'Longest interval used when scheduling the next automatic intelligence reveal.', range:'Seconds; should be at least the minimum.', use:'Raise it to make reveals less predictable and less frequent; lower it for a tighter schedule.', related:'intelligenceRevealIntervalMinSeconds, intelligenceRevealProbability', example:'The system chooses the next reveal within the configured interval window.'}
  ,investigationDoorRadiusMeters: {what:'Radius around a building investigation position used to find doors or entrances.', range:'Metres.', use:'Increase it when valid doors are missed; decrease it to avoid selecting doors from neighboring buildings.', related:'maximumInvestigationDoors, buildingQueryHeight, entranceZoneRadiusMeters', example:'A modest radius keeps the investigation attached to the intended building.'}
