  ,mortarHEAimErrorMaximumMeters: {what:'Largest random impact offset for automatic high-explosive mortar fire.', range:'Metres.', use:'Raise it for a wider, less predictable barrage; lower it for more concentrated fire.', related:'mortarHEAimErrorMinimumMeters, mortarHEDelaySeconds, mortarHEMissionBusySeconds', example:'The maximum defines the outer edge of the expected spread.'}
