  ,mortarHEMissionBusySeconds: {what:'Time an automatic high-explosive mortar mission remains busy and resists duplicate requests.', range:'Seconds.', use:'Increase it to prevent overlapping barrages; decrease it when repeated missions are acceptable.', related:'mortarHEDelaySeconds, automatedSupportOrdersPerMinute', example:'The busy period covers the active mission.'}
  ,objectiveProgressShowIntervalSeconds: {what:'Interval between repeated displays of objective progress when periodic display mode is used.', range:'Seconds.', use:'Lower it for more frequent updates; raise it to reduce HUD and message repetition.', related:'objectiveProgressVisibilityMode, showObjectiveProgressHud, objectiveProgressDisplaySeconds', example:'120 seconds shows a progress reminder every two minutes.'}
  ,pendingRequestLifetimeMinutes: {what:'Maximum time a pending support, teleport, or delivery request remains valid before expiring.', range:'Minutes.', use:'Increase it for slower coordination; decrease it to remove stale requests sooner.', related:'RequestTimeoutSeconds, dispatchGlobalPendingOrderLimit, providerFailureCooldownSeconds', example:'A short lifetime prevents old requests from executing unexpectedly.'}
  ,persistenceRestoreBatchDelayMilliseconds: {what:'Pause between batches while persistent entities are restored after a restart.', range:'Milliseconds.', use:'Increase it to smooth startup load; decrease it to restore the world faster.', related:'persistenceRestoreBatchSize, persistenceRestoreInitialDelaySeconds, persistenceEnabled', example:'100 ms spaces restoration work.'}
  ,persistenceRestoreBatchSize: {what:'Number of persistent entities restored in one batch.', range:'Whole number.', use:'Raise it for faster recovery; lower it to reduce startup spikes.', related:'persistenceRestoreBatchDelayMilliseconds, persistenceRestoreInitialDelaySeconds', example:'1 restores one entity per batch.'}
  ,persistenceRestoreInitialDelaySeconds: {what:'Delay after startup before persistent-entity restoration begins.', range:'Seconds.', use:'Increase it to let other systems initialize first; decrease it for quicker recovery.', related:'persistenceRestoreBatchSize, persistenceRestoreBatchDelayMilliseconds, generationDelaySeconds', example:'A 30-second delay gives the mission time to settle.'}
  ,playerBuiltAreaExclusionRadiusMeters: {what:'Radius around player-built structures where automatic placement or generation is avoided.', range:'Metres.', use:'Increase it to protect player construction; decrease it when usable map space is limited.', related:'baseExclusionRadiusMeters, missionExclusionRadiusMeters, maximumPlacementAttempts', example:'A larger radius keeps generated defenses away from player bases.'}
  ,playerIndirectOrdersIgnoreCivilianAndFriendlySafety: {what:'Allows player-requested indirect fire to ignore normal civilian and friendly safety filters.', range:'Boolean: true or false.', use:'Keep false for safer gameplay; enable only for controlled scenarios where the player accepts the consequences.', related:'aiFriendlyPlayerSafetyEnabled, aiFriendlyPlayerSafetyRadiusMeters, alwaysExecutePlayerOrders', example:'false preserves civilian and friendly-protection checks.'}
  ,playerMortarHECooldownSeconds: {what:'Cooldown between player-requested high-explosive mortar missions.', range:'Seconds.', use:'Raise it to limit repeated bombardment; lower it for more responsive player support.', related:'playerMortarHERounds, playerMortarHEDispersalRadiusMeters, playerOrderMinimumDelaySeconds', example:'The player must wait this long before another HE mission.'}
  ,playerMortarHERounds: {what:'Number of high-explosive rounds fired by one player-requested mortar mission.', range:'Whole number.', use:'Raise it for a heavier barrage; lower it to reduce damage, ammunition use, and mission duration.', related:'playerMortarHECooldownSeconds, playerMortarHEDispersalRadiusMeters, playerMortarRoundIntervalSeconds', example:'3 rounds create a small support salvo.'}
  ,playerMortarHEDispersalRadiusMeters: {what:'Radius used to spread player-requested high-explosive mortar impacts around the target.', range:'Metres.', use:'Increase it for area suppression and uncertainty; decrease it for more concentrated fire.', related:'playerMortarHERounds, mortarHEAimErrorMaximumMeters', example:'A 100 m radius spreads impacts over a local target area.'}
  ,playerMortarRoundIntervalSeconds: {what:'Time between individual rounds in a player-requested mortar salvo.', range:'Seconds.', use:'Increase it for a slower, more readable barrage; decrease it for a faster salvo.', related:'playerMortarHERounds, playerMortarHECooldownSeconds, playerOrderMinimumDelaySeconds', example:'A short interval places the salvo rounds close together in time.'}
  ,preserveDeadBodiesOnDefeatOrExpiry: {what:'Keeps dead bodies when a stronghold or generated location is defeated or expires.', range:'Boolean: true or false.', use:'Enable for battlefield persistence; disable to clean the location and reduce entity count.', related:'cleanupCorpses, deadBodyLifetimeMinutes, preserveArsenalOnDefeat', example:'false removes eligible bodies during location cleanup.'}
  ,preserveJeepPatrolsOnDefeat: {what:'Keeps jeep patrols associated with a location after that location is defeated.', range:'Boolean: true or false.', use:'Enable for persistent post-battle traffic; disable to remove defeated-location patrol activity.', related:'preserveDeadBodiesOnDefeatOrExpiry, automaticMaximumDefendingPatrols', example:'false clears the location’s patrols on defeat.'}
  ,removeDestroyedHelicopterWrecks: {what:'Removes destroyed helicopter wreck entities after the configured cleanup or replacement process.', range:'Boolean: true or false.', use:'Enable to reduce wreck clutter and entity count; disable when wrecks should remain as battlefield scenery.', related:'destroyedHelicopterRespawnCooldownMinutes, cleanupCorpses, vehicleMaintenanceIntervalSeconds', example:'true removes eligible wrecks instead of leaving them indefinitely.'}
  ,smokeScreenDelaySeconds: {what:'Delay before an automatic smoke-screen mission fires after it is approved.', range:'Seconds.', use:'Increase it for a more deliberate response; decrease it when smoke should appear quickly.', related:'smokeScreenMissionBusySeconds, enableAutomaticSmokeScreen, smokeTestDelaySeconds', example:'A short delay deploys smoke soon after the request.'}
  ,smokeScreenMissionBusySeconds: {what:'Time an automatic smoke-screen mission remains busy and resists duplicate requests.', range:'Seconds.', use:'Increase it to avoid overlapping smoke missions; decrease it when repeated screens are acceptable.', related:'smokeScreenDelaySeconds, automatedSupportOrdersPerMinute', example:'The busy period covers the active smoke mission.'}
  ,standaloneDroneBatchIntervalSeconds: {what:'Delay between standalone-drone processing batches.', range:'Seconds.', use:'Increase it to reduce periodic server work; decrease it for more responsive drone scanning.', related:'standaloneDroneCoverageRadiusMeters, standaloneDroneFlightSpeedMetersPerSecond, enableStandaloneDrone', example:'A short interval keeps the drone’s coverage state current.'}
