function fieldHtml(f,path,value){const label=path.split('.').at(-1),doc=helpFor(label,value,f.path),confidenceClass=doc.confidence==='Source-backed'?'source':doc.confidence==='WorkshopInfo manual'?'manual':'inferred',confidenceLabel=doc.confidence==='Source-backed'?'Source-backed':doc.confidence==='WorkshopInfo manual'?'WorkshopInfo':'Inferred',help=esc(tooltipHtml(label,value,f.path)),indicator=`<span class="help-confidence ${confidenceClass}" title="${esc(confidenceLabel)} documentation">●</span>`,hint=`<button class="help-trigger" type="button" aria-label="Show complete documentation for ${esc(prettyName(label))} on hover" data-help="${help}">?</button>`;const heading=`<b>${esc(prettyName(label))}</b>${indicator}${hint}`;if(typeof value==='boolean')return `<label class="config-field check-field"><input data-field="${esc(path)}" type="checkbox" ${value?'checked':''}/><span><span class="field-heading">${heading}</span><small>${esc(explain(label,value,f.path))}</small></span></label>`;if(typeof value==='number')return `<label class="config-field"><span><span class="field-heading">${heading}</span><small>${esc(explain(label,value,f.path))}</small></span><input data-field="${esc(path)}" type="number" step="0.01" value="${roundDecimals(value)}"/></label>`;if(typeof value==='string'){const options=optionsFor(label,value);if(options)return `<label class="config-field"><span><span class="field-heading">${heading}</span><small>${esc(explain(label,value,f.path))} Choose one of the known values.</small></span><select data-field="${esc(path)}">${options.map(option=>`<option value="${esc(option)}" ${option===value?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;return `<label class="config-field"><span><span class="field-heading">${heading}</span><small>${esc(explain(label,value,f.path))}</small></span><input data-field="${esc(path)}" type="text" value="${esc(value)}"/></label>`;}return `<label class="config-field wide"><span><span class="field-heading">${heading}</span><small>${esc(explain(label,value,f.path))} Complex value; use Raw JSON below.</small></span><textarea data-field="${esc(path)}" rows="3">${esc(JSON.stringify(value,null,2))}</textarea></label>`;}
function onFieldChange(e){const f=state.selected, value=state.values.get(f.path), path=e.target.dataset.field; let next=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(Number(e.target.value).toFixed(2)):e.target.value; if(e.target.tagName==='TEXTAREA') try{next=JSON.parse(next)}catch{return showToast('This field expects valid JSON')}; setAt(value,path,normalize(next)); state.values.set(f.path,value); renderEditor(); updateValidation();}
function selectFile(path){const file=state.files.find(f=>f.path===path);if(!file)return;state.selected=file;document.querySelectorAll('.file-row').forEach(button=>button.classList.toggle('selected',button.dataset.path===path));renderEditor();updateValidation();}
