async function loadFromDirectory(fileList){const files=Array.from(fileList).filter(f=>f.name.toLowerCase().endsWith('.json'));state.files=[];state.values.clear();for(const file of files){const relative=file.webkitRelativePath||file.name;const marker=relative.indexOf('STW/');const path=marker>=0?relative.slice(marker).replace(/\\/g,'/'):('STW/'+relative.replace(/\\/g,'/'));const parts=path.slice(4).split('/');const name=parts.pop();const folder=parts.join('/');state.files.push({path,folder,name});state.values.set(path,normalize(JSON.parse(await file.text())));}state.files.sort((a,b)=>a.path.localeCompare(b.path));render();updateValidation();showToast('Loaded '+state.files.length+' local JSON files');}
