async function boot(){try{state.files=await (await fetchFresh(manifestUrl())).json();for(const f of state.files){const data=await (await fetchFresh(f.path)).json();state.values.set(f.path,normalize(data));}const manual=await (await fetchFresh('manual-notes.json')).json();Object.entries(manual).forEach(([key,what])=>{if(!parameterHelp[key])parameterHelp[key]={what,confidence:'WorkshopInfo manual'};});buildEnumOptions();addDiagnosticsControl();$('#search').addEventListener('input',e=>{state.filter=e.target.value;render()});render();updateValidation();}catch(e){console.error(e);enableDirectoryFallback('If you opened index.html directly, choose the STW folder below. On a hosted copy, make sure the STW folder and config-manifest.json are deployed beside index.html.');}}
function crc32(bytes){let t=crc32.t||(crc32.t=Array.from({length:256},(_,n)=>{let c=n;for(let i=0;i<8;i++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;}));let c=0xffffffff;for(const b of bytes)c=t[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
