function addZipImport(){const anchor=$('#exportButton');if(!anchor||$('#zipPicker'))return;const panel=document.createElement('div');panel.className='import-panel';panel.innerHTML='<div class="import-heading"><span class="tip-label">IMPORT PROFILE ZIP</span><span id="importStatus">Defaults loaded</span></div><label>Import mode<select id="importMode"><option value="partial">Partial override — keep defaults for missing files</option><option value="exact">Exact profile — use only files in the ZIP</option></select></label><input id="zipPicker" type="file" accept=".zip,application/zip" hidden><button id="importButton" class="secondary-button" type="button">Choose configuration ZIP</button>';anchor.after(panel);$('#importButton').addEventListener('click',()=>$('#zipPicker').click());$('#zipPicker').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{await importZip(file)}catch(error){showToast('Import failed: '+error.message)}e.target.value=''})}
function zipU16(b,o){return b[o]|b[o+1]<<8}function zipU32(b,o){return(b[o]|b[o+1]<<8|b[o+2]<<16|b[o+3]<<24)>>>0}
async function importZip(file){const b=new Uint8Array(await file.arrayBuffer());let end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(zipU32(b,i)===0x06054b50){end=i;break}if(end<0)throw Error('Invalid ZIP');const count=zipU16(b,end+10),central=zipU32(b,end+16);let p=central,imported=new Map();for(let i=0;i<count;i++){const method=zipU16(b,p+10),size=zipU32(b,p+20),nl=zipU16(b,p+28),xl=zipU16(b,p+30),cl=zipU16(b,p+32),off=zipU32(b,p+42),name=new TextDecoder().decode(b.slice(p+46,p+46+nl));if(!name.endsWith('/')&&name.toLowerCase().endsWith('.json')){const ln=zipU16(b,off+26),lx=zipU16(b,off+28),raw=b.slice(off+30+ln+lx,off+30+ln+lx+size);let data=method===0?raw:method===8?new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer()):null;if(!data)throw Error('Unsupported ZIP compression');let path=name.replace(/\\/g,'/'),marker=path.indexOf('STW/');path=marker>=0?path.slice(marker):path.startsWith('STW/')?path:'STW/'+path;try{imported.set(path,normalize(JSON.parse(new TextDecoder().decode(data))))}catch{throw Error('Invalid JSON in '+name)}}p+=46+nl+xl+cl}if(!imported.size)throw Error('No JSON files found');const exact=$('#importMode').value==='exact';state.values=exact?new Map(imported):new Map(defaultValues);state.files=exact?[...imported.keys()].map(path=>{const a=path.slice(4).split('/'),name=a.pop();return{path,name,folder:a.join('/')}}):defaultFiles.map(f=>({...f}));if(!exact)imported.forEach((v,path)=>state.values.set(path,v));state.selected=null;buildEnumOptions();render();updateValidation();$('#importStatus').textContent=(exact?'Exact: ':'Partial: ')+imported.size+' imported';showToast('Imported '+imported.size+' JSON files')}
function styleImportButtons(){const s=document.createElement('style');s.textContent='.top-tools .secondary-button{border:1px solid #304326;background:#172016;color:#d5f782}.top-tools .secondary-button:hover{border-color:#172016;background:#243321;color:#fff}.import-panel{display:grid;gap:8px;margin-top:16px}.import-heading{display:flex;justify-content:space-between;gap:10px;align-items:baseline}.import-heading #importStatus{font-size:11px;color:#51623e;white-space:nowrap}.import-panel label{color:#51623e}.import-panel select{background-color:#111619;color:#e7ece9;border-color:#304326;font-size:12px}.import-panel .secondary-button{width:100%}';document.head.append(s)}
relocateLibrary();promoteExportPanel();adjustTopLayout();styleScrollbars();styleImportButtons();boot().then(()=>{defaultFiles=state.files.map(f=>({...f}));defaultValues=new Map(state.values);addZipImport()});

